import{_ as e,o as a,c as i,a as r}from"./app.83c7065c.js";const v=JSON.parse('{"title":"Vue使用provide-inject特性注入皮肤配置","description":"","frontmatter":{"title":"Vue使用provide-inject特性注入皮肤配置","date":"2020-01-03"},"headers":[],"relativePath":"2020/vue-provide-inject-theme.md","lastUpdated":1786184870000}'),t={name:"2020/vue-provide-inject-theme.md"},d=r('<h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-hidden="true">#</a></h3><p>H5页面主题皮肤切换，有2条路线，一是使用css实现，一是使用js实现。</p><p>其实需求很简单，希望组件本身可以和皮肤主题解耦，这样至少有2个好处：</p><ul><li>更改的时候只用在皮肤设置文件更改一次</li><li>组件本身与主题样式无关，只在需要的时候把组件和主题组合使用，有足够的灵活性</li></ul><h4 id="现有方案的问题" tabindex="-1">现有方案的问题 <a class="header-anchor" href="#现有方案的问题" aria-hidden="true">#</a></h4><p>现有方案使用的less，在每个组件中引入less variables，然后再按照css规则渲染主题。</p><p>其实已经基本够用了，只是必须每个组件分别编写对应主题下的规则，引入了主题和组件的强耦合，不是特别好的设计，也无法做到实时更改主题。</p><p>本来可以用sass的mixin，但同事都比较排斥sass，只好放弃。</p><p>于是考虑尝试js的方案。</p><h4 id="js的方案" tabindex="-1">JS的方案 <a class="header-anchor" href="#js的方案" aria-hidden="true">#</a></h4><p>搜索的过程中看到了vuetify，它的主题实现就用的provide模式，看了文档之后发现这个就是vue版的React context，来了兴趣就试验了一下。</p><p>废话完毕，先看看基本使用</p><h3 id="provide-eject基本使用" tabindex="-1">Provide-Eject基本使用 <a class="header-anchor" href="#provide-eject基本使用" aria-hidden="true">#</a></h3><p>查下vue的官方文档就明白了，2句话：</p><ol><li>父组件配置provide，注入属性</li><li>子组件配置inject，使用属性</li></ol><p>当然vue本身还支持provide-inject之间互传信息的，对于主题来说，内部注入主题已经足够了，所以没有再继续深究这个特性。</p><h3 id="版本一-基本使用" tabindex="-1">版本一：基本使用 <a class="header-anchor" href="#版本一-基本使用" aria-hidden="true">#</a></h3><h3 id="版本二-结合mixin" tabindex="-1">版本二：结合mixin <a class="header-anchor" href="#版本二-结合mixin" aria-hidden="true">#</a></h3><h3 id="版本三-实时换主题" tabindex="-1">版本三：实时换主题 <a class="header-anchor" href="#版本三-实时换主题" aria-hidden="true">#</a></h3>',19),s=[d];function n(h,c,o,p,l,_){return a(),i("div",null,s)}const f=e(t,[["render",n]]);export{v as __pageData,f as default};
